const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define location and time period
  const wilmington = ee.Geometry.Point([-77.9447, 34.2257]);
  const startDate = '2018-01-01';
  const endDate = '2018-12-31';

  // 2. Load GPM precipitation data
  let precipCol = ee.ImageCollection('NASA/GPM_L3/IMERG_V06')
    .filterDate(startDate, endDate)
    .filterBounds(wilmington)
    .select('precipitation');

  const colSize = precipCol.size().getInfo();
  console.log(`GPM Images found: ${colSize}`);

  if (colSize === 0) {
    // Try CHIRPS as backup
    precipCol = ee.ImageCollection('UCSB-CHG/CHIRPS/DAILY')
      .filterDate(startDate, endDate)
      .filterBounds(wilmington)
      .select('precipitation');

    const chirpsSize = precipCol.size().getInfo();
    console.log(`CHIRPS Images found: ${chirpsSize}`);

    if (chirpsSize === 0) {
      console.log('No precipitation data available for 2018');
      console.log('<answer>C1</answer>');
      return;
    }
  }

  // 3. Sum all precipitation over the year
  const totalPrecip = precipCol.sum();

  // 4. Calculate total precipitation at Wilmington
  const result = totalPrecip.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: wilmington,
    scale: 10000,
    maxPixels: 1e9
  });

  const precipMm = result.get('precipitation').getInfo();

  // 5. Check for valid data
  if (precipMm === null || precipMm === undefined || isNaN(precipMm)) {
    console.log('Calculation failed - no valid result');
    console.log('<answer>C3</answer>');
    return;
  }

  if (precipMm < 0) {
    console.log(`Invalid precipitation value: ${precipMm} mm`);
    console.log('<answer>C3</answer>');
    return;
  }

  // Convert mm to inches (1 inch = 25.4 mm)
  const precipInches = precipMm / 25.4;

  console.log(`Total precipitation in 2018: ${precipMm.toFixed(2)} mm (${precipInches.toFixed(2)} inches)`);

  // 6. Determine answer
  if (precipInches >= 90) {
    console.log(`Wilmington received ${precipInches.toFixed(2)} inches, which is >= 90 inches`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`Wilmington received ${precipInches.toFixed(2)} inches, which is < 90 inches`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
